import numpy as np
import cv2
def sliding_windows(img, win=64, step=8, scale=1.25):
    s = 1.0
    while win * s <= min(img.shape[:2]):
        w = int(win * s); st = int(step * s)
        for y in range(0, img.shape[0] - w + 1, st):
            for x in range(0, img.shape[1] - w + 1, st):
                yield x, y, w                     # 窓の左上とサイズ
        s *= scale
img = np.zeros((480, 640), np.uint8)
cv2.rectangle(img, (300, 200), (380, 280), 255, -1)    # 探したい白い四角
dets = []
for x, y, w in sliding_windows(img):
    score = img[y:y+w, x:x+w].mean() / 255     # 仮の識別器：白の割合
    if score > 0.9:
        dets.append((x, y, w, round(score, 2)))
print(len(dets), dets[:3])                     # 複数の窓が反応 → NMS で統合
